INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'bdbb278d-ba6e-50a5-8da0-6728ded1f281', 'd6101c7d-a824-5165-9c8c-e4fcc4bd7cc1',
  'Interactively insert a new node `p` in a Binary search tree (BST)?

Lựa chọn:
- ```c
if (root == NULL) {
    root = p;
} else {
    if (p -> data -> key < root -> data -> key) {
        insertBST(root -> left, p);
    } else {
        insertBST(root -> right, p);
    }
}
```
- ```c
if (root == NULL) {
    root = p;
}
}
```
- ```c
if (root == NULL) {
    root = p;
} else {
    walk = root;
    while (walk != NULL) {
        parent = walk;
        if (p -> data -> key < walk -> data -> key) {
            walk = walk -> left;
        } else {
            walk = walk -> right;
        }
    }
    if (p -> data -> key < parent -> data -> key) {
        parent -> left = p;
    } else {
        parent -> right = p;
    }
}
```
- ```c
if (root == NULL) {
    root = p;
} else {
    pw = root;
    while (pw != NULL) {
        pr = pw;
        if (p -> data -> key > pw -> data -> key) {
            pw = pw -> left;
        } else {
            pw = pw -> right;
        }
    }
    if (p -> data -> key > pr -> data -> key) {
        pr -> left = p;
    } else {
        pr -> right = p;
    }
}
```', 17
);

